// GroupByParam groups by the given page parameter key's value and with the given order.
// Valid values for order is asc, desc, rev and reverse.
func (p Pages) GroupByParam(key string, order ...string) (PagesGroup, error) {
	if len(p) < 1 {
		return nil, nil
	}

	direction := "asc"

	if len(order) > 0 && (strings.ToLower(order[0]) == "desc" || strings.ToLower(order[0]) == "rev" || strings.ToLower(order[0]) == "reverse") {
		direction = "desc"
	}

	var tmp reflect.Value
	var keyt reflect.Type
	for _, e := range p {
		param := pageParam(e, key, true)
		if param != nil {
			if _, ok := param.([]string); !ok {
				keyt = reflect.TypeOf(param)
				tmp = reflect.MakeMap(reflect.MapOf(keyt, pagesType))
				break
			}
		}
	}
	if !tmp.IsValid() {
		return nil, errors.New("there is no such param")
	}

	return (PageGroup{Key: key, Pages: p}).collectParamGroups(direction, keyt)
}

func pageParam(e Page, key string, stringToLower bool) any {
	if e == nil {
		return nil
	}
	return normalizeParam(e.Params()[strings.ToLower(key)], stringToLower)
}

func normalizeParam(v any, stringToLower bool) any {
	if v == nil {
		return nil
	}

	switch val := v.(type) {
	case bool:
		return val
	case string:
		if stringToLower {
			return strings.ToLower(val)
		}
		return val
	case int64, int32, int16, int8, int:
		return cast.ToInt(v)
	case float64, float32:
		return cast.ToFloat64(v)
	case time.Time:
		return val
	case toml.LocalDate:
		return val.AsTime(time.UTC)
	case toml.LocalDateTime:
		return val.AsTime(time.UTC)
	case []string:
		if stringToLower {
			return helpers.SliceToLower(val)
		}
		return v
	case map[string]any:
		return v
	case map[any]any:
		return v
	}
	return nil
}

func (g PageGroup) collectParamGroups(direction string, keyt reflect.Type) (PagesGroup, error) {
	key, _ := g.Key.(string)
	pages := g.Pages
	if len(pages) == 0 {
		return nil, nil
	}

	example := pages[0]
	exampleWeight := example.Weight()
	exampleDate := example.Date()
	examplePath := example.Path()
	exampleTitle := example.Title()
	exampleFile := ""
	if f := example.File(); f != nil {
		exampleFile = f.Filename()
	}

	tmp := reflect.MakeMap(reflect.MapOf(keyt, pagesType))
	for _, e := range pages {
		params := e.Params()
		var raw any
		if params != nil && !params.IsZero() {
			raw = params[strings.ToLower(key)]
		}
		param := normalizeParam(raw, false)

		weight := e.Weight()
		date := e.Date()
		path := e.Path()
		title := e.Title()
		filename := ""
		if f := e.File(); f != nil {
			filename = f.Filename()
		}

		if param != nil && reflect.TypeOf(param) == keyt {
			better := false
			switch {
			case weight != exampleWeight:
				better = weight < exampleWeight
			case !date.Equal(exampleDate):
				better = date.Before(exampleDate)
			case path != examplePath:
				better = path < examplePath
			case title != exampleTitle:
				better = title < exampleTitle
			case filename != exampleFile:
				better = filename < exampleFile
			}
			if better {
				example = e
				exampleWeight = weight
				exampleDate = date
				examplePath = path
				exampleTitle = title
				exampleFile = filename
			}
		}

		if param == nil || reflect.TypeOf(param) != keyt {
			continue
		}
		v := reflect.ValueOf(param)
		if !tmp.MapIndex(v).IsValid() {
			tmp.SetMapIndex(v, reflect.MakeSlice(pagesType, 0, 0))
		}
		tmp.SetMapIndex(v, reflect.Append(tmp.MapIndex(v), reflect.ValueOf(e)))
	}

	var r []PageGroup
	for _, k := range sortKeys(example, tmp.MapKeys(), direction) {
		r = append(r, PageGroup{Key: k.Interface(), Pages: tmp.MapIndex(k).Interface().(Pages)})
	}
	return r, nil
}

func (p Pages) groupByDateField(format string, sorter func(p Pages) Pages, getDate func(p Page) time.Time, order ...string) (PagesGroup, error) {
	if len(p) < 1 {
		return nil, nil
	}

	sp := sorter(p)

	if !(len(order) > 0 && (strings.ToLower(order[0]) == "asc" || strings.ToLower(order[0]) == "rev" || strings.ToLower(order[0]) == "reverse")) {
		sp = sp.Reverse()
	}

	if sp == nil {
		return nil, nil
	}

	firstPage := sp[0]
	date := getDate(firstPage)

	// Pages may be a mix of multiple languages, so we need to use the language
	// for the currently rendered Site.
	currentSite := firstPage.Site().Current()
	formatter := langs.GetTimeFormatter(currentSite.Language())
	formatted := formatter.Format(date, format)
	var r []PageGroup
	r = append(r, PageGroup{Key: formatted, Pages: make(Pages, 0)})
	r[0].Pages = append(r[0].Pages, sp[0])

	i := 0
	for _, e := range sp[1:] {
		date = getDate(e)
		formatted := formatter.Format(date, format)
		if r[i].Key.(string) != formatted {
			r = append(r, PageGroup{Key: formatted})
			i++
		}
		r[i].Pages = append(r[i].Pages, e)
	}
	return r, nil
}

// GroupByDate groups by the given page's Date value in
// the given format and with the given order.
// Valid values for order is asc, desc, rev and reverse.
// For valid format strings, see https://golang.org/pkg/time/#Time.Format
func (p Pages) GroupByDate(format string, order ...string) (PagesGroup, error) {
	sorter := func(p Pages) Pages {
		return p.ByDate()
	}
	getDate := func(p Page) time.Time {
		return p.Date()
	}
	return p.groupByDateField(format, sorter, getDate, order...)
}

